<template>
  <header>
    <nav>
      <a class="logo" href="https://www.sinyi.com.tw/" target="_blank"><img src="@/assets/images/logo.png" /></a>
      <div id="menu-btn" @click="toggleMenu()"></div>
      <div id="popup-component" v-if="showMenu">
        <div class="menu" :class="{ expand: showMenu }">
          <button class="popup-close" @click="toggleMenu()"></button>
          <ul>
            <li class="menu-popup" @click="toggleMenu('isActivity')">活動辦法</li>
            <li class="menu-popup" @click="toggleMenu('isBranding')">
              信義大事紀
            </li>
            <li>
              <a
                href="https://www.sinyi.com.tw/buy/list"
                target="_blank"
                @click="toggleMenu('isOfficialSite')"
                >信義官網</a
              >
            </li>
          </ul>
        </div>
      </div>
      <PopupActivity v-if="isActivity" />
      <PopupBranding v-if="isBranding" />
    </nav>
  </header>
</template>

<script>
import { mapState, mapMutations } from "vuex";
import { mixins } from "@/utils/mixins";
import PopupActivity from "./PopupActivity.vue";
import PopupBranding from "./PopupBranding.vue";

export default {
  name: "Header",
  mixins: [mixins],
  props: {},
  data: () => {
    return {
      showMenu: false,
      scrollPosition: null,
      hidePopup: true,
      isActivity: false,
      isBranding: false,
    };
  },
  computed: {
    ...mapState([]),
  },
  methods: {
    ...mapMutations([]),
    addScrollStyle() {
      const bodyItem = document.querySelector("body");
      this.scrollPosition = window.scrollY;
      bodyItem.classList.add("scroll-style");
      bodyItem.style.top = -this.scrollPosition + "px";
    },
    removeScrollStyle() {
      const bodyItem = document.querySelector("body");
      bodyItem.classList.remove("scroll-style");
      bodyItem.style.removeProperty("top");
      window.scrollTo(0, this.scrollPosition);
    },
    toggleMenu(type) {
      this.showMenu = !this.showMenu;
      if (this.showMenu) {
        this.addScrollStyle();
      } else {
        this.removeScrollStyle();
      }
      setTimeout(() => {
        if (type === "isActivity") {
          this.isActivity = true;
          this.isBranding = false;
          this.addScrollStyle();
        } else if (type === "isBranding") {
          this.isActivity = false;
          this.isBranding = true;
          this.addScrollStyle();
        }else{
        this.isActivity = false;
        this.isBranding = false;
        this.removeScrollStyle()
      }
      }, 100);

      let clickName = 
        (type === 'isActivity') ? '活動辦法' :
        (type === 'isBranding') ? '信義大事紀' :
        (type === 'isOfficialSite') ? '信義官網' : '';

      if (clickName) {
        this.$pushDataLayer({
          event: "syev_2023tvc",
          sy_event: "menu_click",
          click_name: clickName
        });
      }
      // return (this.showMenu = !this.showMenu);
      // this.$trackEvent("menu", item.gaAction, item.gaLabel);
    },
    resetScroll() {
      window.scrollTo(0, 0);
    },
    gaClickKarate() {
      // this.$trackEvent("more", "click_button", "more_karate");
    },
  },
  mounted() {},
  components: {
    PopupActivity,
    PopupBranding,
  },
};
</script>

<style lang="scss" scoped>
$assets: "~@/assets/images/";

/* 選單 */
header {
  display: none;
  @include position-center(fixed);
  top: 0;
  z-index: 99;
  font-family: $fontFamilyNotoSerif;
  @include tablet {
    // background: linear-gradient(0deg, #dcf2de00, #dcf2de 60%);
    background: linear-gradient(0deg, #f9fdf900, #f9fdf9 75%);
    display: block;
    width: 100%;
    height: 15%;
  }
}
nav {
  @include flex-center;
  width: 100%;
  position: fixed;
  z-index: 99;
  top: 0;
  @include tablet {
    justify-content: space-between;
    padding: vw(24) vw(50);
    #popup-component {
      left: 0;
    }
  }
}
.logo {
  img {
    width: vw(230);
  }
}

#menu-btn {
  display: none;
  @include tablet {
    display: block;
    cursor: pointer;
    width: vw(69);
    height: vw(39);
    background: url($assets + "icon-menu.png") no-repeat center/contain;
  }
}
.menu {
  @include tablet {
    @include position-center(fixed);
    font-family: $fontFamilyNotoSerif;
    // max-height: 0px;
    height: 0px;
    overflow: hidden;
    transition: all 0.5s;
    // top: 10px;
    left: 0;
    right: 0;
    margin: 0 auto;
    // right: vw(20);
    top: 50%;
    transform:  translateY(-50%);
    width: vw(460);
    z-index: 100;
    // background: $ciColor;
    text-align: center;
    border-radius: vw(20);
    background: url($assets + "bg-menu.png") no-repeat top/contain $ciColor;

  }
  ul {
    @include tablet {
      display: block;
      position: relative;
      top: 50%;
      transform: translateY(-50%);
      padding-top: vw(170);
      
    }
    li {
      @include tablet {
        padding: 0;
        width: vw(335);
        margin: 0 auto;
        
      }
      &:last-child {
        @include tablet {
          a {
            border: 0;
          }
        }
      }
    }
    a,
    .menu-popup {
      @include tablet {
        color: #fff;
        font-size: vw(49);
        text-align: center;
        padding: vw(63) 0;
        letter-spacing: 2vw;
        display: block;
        border-bottom: 1px solid #fff;
        margin: 0 auto;
        white-space: nowrap;
      }
      &:hover {
        @include tablet {
          background: none;
          border-radius: 0;
        }
      }
    }
  }
}
.expand {
  @include tablet {
    height: vw(690);
    // height: 100vh;
    // height: calc(var(--vh, 1vh) * 100 - 60px);
    ul {
      top: 0;
      transform: none;
    }
  }
}
</style>
