<template>
  <div id="popup-component" class="popup__block popup-infor">
    <div class="popup-content">
      <div class="popup-box">
        <button class="popup-close" @click.prevent="hidePopupAct"></button>
        <p class="trans-title">填寫抽獎資料</p>
        <p class="trans-text">
          恭喜你獲得蘭城晶英住宿券抽獎資格<br />請留下聯絡方式，以便後續中獎通知<br />
        </p>
        <p class="trans-text">
          40多年來，持續用心理解每個需求<br />您買賣房屋的大小事<br />請交給值得信任的信義房屋
        </p>
        <div class="popup-infro">
          <div class="popup-form">
            <label for=""
              ><span><small class="star-key">*</small>姓 名</span
              ><input type="text" v-model="userName" @blur="saveUserName"
            /></label>
            <label for=""
              ><span><small class="star-key">*</small>手 機</span
              ><input
                type="tel"
                v-model="userTel"
                @blur="setNumber"
                maxlength="10"
            /></label>
            <div class="address-choice">
              <label for="">
                <span><small class="star-key">*</small>地 址</span>
                <div>
                  <select
                    class=""
                    v-model="selectedCity"
                    @change="saveActiveCity"
                  >
                    <option disabled selected hidden>請選擇</option>
                    <option
                      v-for="cityItem in cityInfo"
                      :key="cityItem.cityId"
                      :value="cityItem.cityId"
                    >
                      {{ cityItem.cityName }}
                    </option>
                  </select>
                  <select class="" v-model="selectedZip" @change="saveZipCode">
                    <option disabled selected hidden>請選擇</option>
                    <option
                      v-for="zipsItem in getActiveZips"
                      :key="zipsItem.zipCode"
                      :value="zipsItem.zipCode"
                    >
                      {{ zipsItem.zipName }}
                    </option>
                  </select>
                  <br />
                  <select
                    v-if="hasRoad"
                    class=""
                    v-model="selectedRoad"
                    @blur="setRoadName(selectedRoad)"
                  >
                    <option disabled selected hidden>請選擇</option>
                    <option
                      v-for="roadItem in allRoads"
                      :key="roadItem.roadId"
                      :value="roadItem.roadName"
                    >
                      {{ roadItem.roadName }}
                    </option>
                  </select>
                  <input
                    v-else
                    class="roads-sytle"
                    type="address"
                    placeholder="輸入路名"
                    v-model="userRoads"
                    @blur="setRoadName(userRoads)"
                  />
                  <br />
                  <input
                    type="address"
                    placeholder="請填寫正確抽獎地址"
                    v-model="userAddress"
                    @blur="setAddress(userAddress)"
                  />
                </div>
              </label>
            </div>
            <div class="form-chptcha">
              <label for="">
                <span><small class="star-key">*</small>驗證碼</span>
                <input
                  type=""
                  v-model="userOtpCode"
                  @blur="setOtpCode(userOtpCode)"
                  maxlength="6"
                />
              </label>
              <p class="form-chptcha-send" @click="sendOtp()">寄送驗證碼</p>
            </div>
            <label for="isAgreed" class="form-must-check">
              <input id="isAgreed" type="checkbox" v-model="isAgreed" /><small
                class="star-key"
                >*</small
              >我同意信義房屋的<a
                href="https://www.sinyi.com.tw/privacy "
                target="_blank"
                >個資保護之相關規定</a
              >。
            </label>
          </div>
          <div class="popup-agree">
            <label for="buyHouse" class="agree-check">
              <input
                id="buyHouse"
                type="checkbox"
                v-model="buyHouse"
                @change="setBuyHouse(buyHouse)"
              />近期在看房，請專員主動聯繫我</label
            >
            <label for="sellHouse" class="agree-check"
              ><input
                id="sellHouse"
                type="checkbox"
                v-model="sellHouse"
                @change="setSellHouse(sellHouse)"
              />近期想賣房，請專員主動聯繫我</label
            >
          </div>
          <button class="popup-btn" @click="saveRet">確認無誤送出</button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
// import { mapState, mapMutations } from 'vuex'
import { mapActions, mapState } from "pinia";
import { useMainStore } from "@/store/main";
import axios from "axios";
export default {
  name: "PopupForm",
  props: [],
  data: () => {
    return {
      selectedCity: "請選擇",
      selectedZip: "請選擇",
      selectedRoad: "請選擇",
      userRoads: "",
      userAddress: "",
      userName: "",
      userTel: "",
      allRoads: [],
      userOtpCode: "",
      buyHouse: false,
      sellHouse: false,
      hidePopup: false,
      isAgreed: false,
      hasRoad: true,
    };
  },
  computed: {
    ...mapState(useMainStore, [
      "cityInfo",
      "dataForSendOtp",
      "getActiveZips",
      "dataForGetRoads",
      "dataForSaveRet",
      "quizType",
      "changeBtn",
      "showForm",
    ]),
  },
  methods: {
    ...mapActions(useMainStore, [
      "setUserName",
      "setUserPhone",
      "setUserName",
      "setActiveCity",
      "setActiveZipCode",
      "setOtpToken",
      "setOtpCode",
      "setBuyHouse",
      "setSellHouse",
      "setAddress",
      "setRoadName",
      "setUid",
      "setShareUrl",
      "setLoading",
      "setChangeBtn",
      "setShowForm",
    ]),
    sendOtp() {
      const self = this;
      self.setLoading(true);
      axios
        .post("/api/data/sendOTP", self.dataForSendOtp)
        .then(function (res) {
          console.log(res);
          const { rs, msg, item } = res.data;
          self.setLoading(false);
          if (!item.content) {
            alert(item.retMsg);
            return;
          }
          self.setOtpToken(item.content.otpToken);
          if (item.content.eventsStauts === 4) {
            alert(
              "感謝您的參與，先前已收到您的抽獎資料，「中獎名單」將於2023/12/15公佈於信義房屋FB粉絲專頁中，歡迎追蹤按讚唷！"
            );
            // self.hidePopup = !self.hidePopup;
            self.setShowForm(!self.showForm);
            self.setChangeBtn(!self.changeBtn);
            const bodyItem = document.querySelector("body");
            bodyItem.classList.remove("scroll-style");
            window.scrollTo(0, self.popupPosition);
            return;
          }
          if (item.content.eventsStauts === 3) {
            if (process.env.VUE_APP_ENV === "production") {
              alert("簡訊驗證碼已發送");
            } else {
              alert(item.debugMsg);
            }
          }

          // const sid = item.sid;
          // const uid = item.content.uid;
          // self.setCityInfo(citys);
          // self.setSid(sid);
          // self.setUid(uid);
          // formCitys = citys;
          // console.log(formCitys);
          // if (rs !== "OK") {
          //   alert("發生錯誤，請稍後再試");
          //   return;
          // }
          // if (msg && item === null) {
          //   alert(msg);
          //   return;
          // }
          // if (item === null) {
          //   return;
          // }
          // console.log(res);
        })
        .catch((error) => {
          // this.$router.push({ path: /home });
          self.setLoading(false);
          alert(error.response.data.msg);
          console.error(error);
        });
    },
    setNumber() {
      this.setUserPhone(this.userTel);
    },
    saveUserName() {
      // 驗證髒字
      this.setUserName(this.userName);
    },
    saveActiveCity() {
      this.setActiveCity(this.selectedCity);
    },
    saveZipCode() {
      this.setActiveZipCode(this.selectedZip);
      this.getRoadName();
    },
    getRoadName() {
      const self = this;
      self.setLoading(true);
      axios
        .post("/api/data/getRoads", self.dataForGetRoads)
        .then(function (res) {
          console.log(res);
          const { rs, msg, item } = res.data;
          console.log(item);
          if (item.retResult !== false) {
            self.allRoads = item.content.roads;
            self.hasRoad = true;
          } else {
            self.hasRoad = false;
          }
          self.setLoading(false);
          // const { citys } = item.content.cityInfo;
          // const sid = item.sid;
          // const uid = item.content.uid;
          // self.setCityInfo(citys);
          // self.setSid(sid);
          // self.setUid(uid);
          // formCitys = citys;
          // console.log(formCitys);
          // if (rs !== "OK") {
          //   alert("發生錯誤，請稍後再試");
          //   return;
          // }
          // if (msg && item === null) {
          //   alert(msg);
          //   return;
          // }
          // if (item === null) {
          //   return;
          // }
          // console.log(res);
        })
        .catch((error) => {
          // this.$router.push({ path: /home });
          self.setLoading(false);
          console.error(error);
        });
    },
    saveRet() {
      const { $pushDataLayer, quizType } = this;
      const self = this;
      if (self.userOtpCode.length !== 6) {
        alert("請輸入六位數字驗證碼");
      }
      if (this.userName == "") {
        alert("請輸入姓名");
      } else if (this.userTel == "") {
        alert("請輸入手機號碼");
      } else if (
        this.selectedCity == "請選擇" ||
        this.selectedZip == "請選擇"
      ) {
        alert("請選擇地址");
      } else if (this.hasRoad && this.selectedRoad == "請選擇") {
        alert("請選擇地址");
      } else if (!this.hasRoad && this.userRoads == "請選擇") {
        alert("請輸入地址");
      } else if (this.userAddress == "") {
        alert("請輸入巷弄號");
      } else if (this.userOtpCode == "") {
        alert("請輸入驗證碼");
      } else if (!this.isAgreed) {
        alert("請勾選同意個資保護之相關規定");
      } else {
        self.setLoading(true);
        axios
          .post("/api/data/saveRet", self.dataForSaveRet)
          .then(function (res) {
            console.log(res);
            const { rs, msg, item } = res.data;
            // self.setUid(item.content.uid);
            // self.setShareUrl(msg);
            self.setLoading(false);
            if (!item.content) {
              alert(item.retCode);
              return;
            }
            if (
              item.content.eventsStauts === 3 &&
              item.content.verifyStatus === false
            ) {
              alert("驗證碼輸入錯誤");
              return;
            }
            if (
              item.content.eventsStauts === 3 &&
              item.content.verifyStatus === true
            ) {
              alert(
                "資料送出成功！感謝您的參與，分享活動至個人Facebook並設定公開，再加碼抽星宇航空東京雙人來回機票唷！"
              );
            }
            if (item.content.eventsStauts === 4) {
              alert(
                "感謝您的參與，先前已收到您的抽獎資料，每筆使用者資料僅限一次抽獎機會。「中獎名單」將於2023/12/15公佈於信義房屋FB粉絲專頁中，歡迎追蹤按讚唷！"
              );
            }
            // self.hidePopup = !self.hidePopup;
            self.setShowForm(!self.showForm);
            const bodyItem = document.querySelector("body");
            bodyItem.classList.remove("scroll-style");
            window.scrollTo(0, self.popupPosition);
            self.setChangeBtn(!self.changeBtn);

            // const { citys } = item.content.cityInfo;
            // const sid = item.sid;
            // const uid = item.content.uid;
            // self.setCityInfo(citys);
            // self.setSid(sid);
            // self.setUid(uid);
            // formCitys = citys;
            // console.log(formCitys);
            // if (rs !== "OK") {
            //   alert("發生錯誤，請稍後再試");
            //   return;
            // }
            // if (msg && item === null) {
            //   alert(msg);
            //   return;
            // }
            // if (item === null) {
            //   return;
            // }
            // console.log(res);
          })
          .catch((error) => {
            // this.$router.push({ path: /home });
            self.setLoading(false);
            alert(error.response.data.msg);
            console.log(error);
            console.error(error);
          });

        let intent =
          this.buyHouse === true && this.sellHouse === true
            ? "皆有"
            : this.buyHouse === true && this.sellHouse === false
            ? "買方"
            : this.buyHouse === false && this.sellHouse === true
            ? "賣方"
            : "無";
        $pushDataLayer({
          event: "syev_2023tvc",
          sy_event: "tvc_form_submit",
          intent,
          quiz_type: quizType,
        });
      }
    },
    hidePopupAct() {
      // this.hidePopup = true;
      const bodyItem = document.querySelector("body");
      bodyItem.classList.remove("scroll-style");
      window.scrollTo(0, this.popupPosition);
      this.setShowForm(!this.showForm);
    },
  },
  mounted() {},
  components: {},
};
</script>

<style lang="scss">
$assets: "~@/assets/images/home/";
$assetsResult: "~@/assets/images/result/";

#popup-component {
  @include tablet {
    position: fixed;
    z-index: 100;
    top: 0;
    width: 100%;
    // height: 100%;
    min-height: calc(var(--vh, 1vh) * 100);
    background: rgba(0, 0, 0, 0.6);
    // display: none;
    overflow-y: auto;
  }
}

.popup-content {
  @include tablet {
    position: absolute;
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: calc(var(--vh, 1vh) * 100);
    // top: 50%;
    // transform: translateY(-50%);
  }
}

.popup-box {
  @include tablet {
    position: relative;
    display: flex;
    justify-content: center;
    flex-direction: column;
    background: #f1fcec;
    border-radius: 5px;
    width: vw(720);
    margin: 0 auto;
    text-align: center;
    // padding: vw(100) vw(50);
    padding: 0 vw(50);
    min-height: vw(1258);
    .trans-title {
      padding-bottom: vw(25);
      border-bottom: vw(2) solid $ciColor;
      font-weight: 800;
    }
  }
}
.popup-infor {
  @include tablet {
    .popup-box {
      padding: vw(110) vw(50);
      margin: vw(40) auto vw(52) auto;
      overflow-y: auto;
    }
    .popup-content {
      top: 0;
      transform: none;
    }
    .trans-title {
      letter-spacing: 0.5vw;
      font-size: vw(58);
    }
    .trans-text {
      font-weight: 700;
      font-size: vw(34);
      + .trans-text {
        margin-top: 0;
      }
    }
  }
}
.popup-infro {
  @include tablet {
    // margin-top: vw(30)
  }
}
%checkboxStyle {
  gap: 0 vw(6);
  font-size: vw(25);
  letter-spacing: 0.5px;
  input[type="checkbox"] {
    position: relative;
    appearance: none;
    background: #fff;
    box-shadow: vw(3) vw(3) 0 $ciColor;
    width: vw(40);
    height: vw(40);
    border-radius: 0;
    border: 0;
    &::after {
      content: "\2714";
      position: absolute;
      left: vw(2);
      top: vw(-8);
      text-align: center;
      color: $ciColor;
      width: 100%;
      height: auto;
      transition: 0.2s;
      opacity: 0;
    }
    &:checked::after {
      opacity: 1;
    }
  }
}
.popup-form {
  @include tablet {
    width: vw(545);
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: vw(25) 0;
    text-align: left;
    label {
      display: flex;
      align-items: center;
      justify-content: space-between;
      white-space: nowrap;
      font-size: vw(34);
      line-height: vw(48);
      span {
        display: block;
        margin-right: vw(15);
        min-width: vw(130);
        letter-spacing: vw(15);
      }
    }
    input {
      height: vw(48);
      // width: 100%;
      width: vw(400);
      border: 0;
      font-size: vw(32);
      color: #3e3a39;
      padding: 0 vw(10);
      border-radius: 0;
      font-family: $fontFamilyNotoSerif;
    }
    .address-choice {
      width: 100%;
      label {
        align-items: flex-start;
      }
      select {
        border-radius: 0;
        appearance: none;
        font-family: $fontFamilyNotoSerif;
        width: 100%;
        height: vw(48);
        font-size: vw(32);
        border: 0;
        padding: 0 vw(10);
        margin-bottom: vw(12);
        color: #3e3a39;
        & + select {
          margin-left: vw(23);
        }
        &:nth-child(1),
        &:nth-child(2) {
          width: vw(188);
        }
        &::placeholder,
        &::-webkit-input-placeholder {
          color: #3e3a3950;
        }
      }
      .roads-sytle {
        margin-bottom: vw(12);
      }
    }
    .form-chptcha {
      display: flex;
      align-items: center;
      &-send {
        font-size: vw(27);
        color: #74c8e2;
        text-decoration: underline;
        text-underline-offset: vw(8);
        margin-left: vw(18);
        word-break: keep-all;
      }
      span {
        letter-spacing: 1px;
      }
      input {
        width: 100%;
      }
    }
    select {
      appearance: none;
      position: relative;
      background: url($assetsResult + "icon-arrow.jpg") no-repeat right/contain
        #fff;
    }
    select:hover,
    select:focus-visible {
      outline-color: transparent;
    }
  }
  .form-must-check {
    @extend %checkboxStyle;
    justify-content: space-around;
    gap: 0;
    font-weight: 600;
    a {
      color: #74c8e2;
      text-decoration: underline;
    }
  }
}
.popup-agree {
  margin: vw(35) 0 vw(33);
  .agree-check {
    @include flex-center;
    justify-content: center;
    font-size: vw(29);
    font-weight: 600;
    @extend %checkboxStyle;
    input {
      font-size: vw(36);
    }
  }
}
.popup {
  &-btn {
    @include tablet {
      background: $ciColor;
      color: #fff;
      font-size: vw(35);
      padding: vw(13) vw(40) vw(15);
      border-radius: vw(10);
      font-family: $fontFamilyNotoSerif;
      font-weight: 700;
      letter-spacing: 2px;
      border: 0;
      cursor: pointer;
    }
  }
  &-close {
    @include tablet {
      border: 0;
      position: absolute;
      z-index: 5;
      top: vw(30);
      right: vw(25);
      background: transparent;
      cursor: pointer;
      width: vw(85);
      height: vw(85);
      background: url($assetsResult + "icon-close.png") no-repeat center/cover;
    }
    span {
      @include tablet {
        height: vw(70);
        position: absolute;
        top: 0;
        display: block;
        width: 1px;
        background: $colorText;
        &:first-child {
          transform: rotate(-45deg);
        }
        &:last-child {
          transform: rotate(45deg);
        }
      }
    }
  }
}

.star-key {
  color: red;
  letter-spacing: 1px;
}
</style>
