import { defineStore } from 'pinia';

// 這邊 defineStore 會自動動態註冊模組，回傳值為 hook function
export const useMainStore = defineStore('Main', {
  // 注意 state 是一個 function，推薦使用 arrow function
  // 可幫助 typescript 更好進行類型推斷
  state: () => ({
    isLoading: false,
    popup: null,
    // 本人
    user: {
      sid: '',
      uid: 0,
      name: '',
      nickName: '',
      phoneNum: '',
      answer: {
        q1: '',
        q2: '',
        q3: '',
        q4: '',
        q5: '',
        q6: '',
      },
      result: '',
      buyHouse: false,
      sellHouse: false,
    },
    utm: {
      utmSource: '',
      utmMedium: '',
      utmCampaign: '',
      utmContent: '',
      utmTerm: '',
      utmCode: '',
    },
    cityInfo: [],
    acitveCity: '',
    activeZipCode: '',
    roadName: '',
    address: '',
    otp: {

    },
    social: {
      fb: false,
      line: false,
      ig: false,
    },
    shareUrl: '',
    otherUserInfo: {
      shareid: 0
    },
    otherUid: 0,
    changeBtn: false,
    showForm: false,
    storeId:'',
    agentId:'',
  }),
  // 只是運算資料，不動原始值
  getters: {
    quizType(state) {
      const { otherUid } = state;
      return otherUid ? '配對測驗' : '個人測驗';
    },
    dataForGetCitys(state) {
      let obj = {
        sid: state.user.sid,
        utmSource: state.utm.utmSource,
        utmMedium: state.utm.utmMedium,
        utmCampaign: state.utm.utmCampaign,
        utmContent: state.utm.utmContent,
        utmTerm: state.utm.utmTerm,
        utmCode: state.utm.utmCode,
      };
      return obj;
    },
    dataForSendOtp(state) {
      let obj = {
        phoneNumber: state.user.phoneNum,
        utmSource: state.utm.utmSource,
        utmMedium: state.utm.utmMedium,
        utmCampaign: state.utm.utmCampaign,
        utmContent: state.utm.utmContent,
        utmTerm: state.utm.utmTerm,
        utmCode: state.utm.utmCode,
        sid: state.user.sid,
        uid: state.user.uid,
        nickName: state.user.nickName,
        answer: {
          q1: state.user.answer.q1,
          q2: state.user.answer.q2,
          q3: state.user.answer.q3,
          q4: state.user.answer.q4,
          q5: state.user.answer.q5,
          q6: state.user.answer.q6,
        },
        result: state.user.result,
      };
      return obj;
    },
    dataForGetRoads(state) {
      let obj = {
        zipCode: state.activeZipCode,
        utmSource: state.utm.utmSource,
        utmMedium: state.utm.utmMedium,
        utmCampaign: state.utm.utmCampaign,
        utmContent: state.utm.utmContent,
        utmTerm: state.utm.utmTerm,
        utmCode: state.utm.utmCode,
        sid: state.user.sid,
      };
      return obj;
    },
    dataForSaveRet(state) {
      let obj = {
        phoneNumber: state.user.phoneNum,
        name: state.user.name,
        nickname: state.user.nickName,
        cityId: state.acitveCity,
        zipCode: state.activeZipCode,
        roadName: state.roadName,
        address: state.address,
        sid: state.user.sid,
        uid: state.user.uid,
        sharedUid: state.otherUserInfo.shareid,
        buyHouse: state.user.buyHouse,
        sellHouse: state.user.sellHouse,
        answer: {
          q1: state.user.answer.q1,
          q2: state.user.answer.q2,
          q3: state.user.answer.q3,
          q4: state.user.answer.q4,
          q5: state.user.answer.q5,
          q6: state.user.answer.q6,
        },
        result: state.user.result,
        utmSource: state.utm.utmSource,
        utmMedium: state.utm.utmMedium,
        utmCampaign: state.utm.utmCampaign,
        utmContent: state.utm.utmContent,
        utmTerm: state.utm.utmTerm,
        utmCode: state.utm.utmCode,
        otpToken: state.otp.otpToken,
        otpCode: state.otp.otpCode,
        storeId:state.storeId,
        agentId:state.agentId
      };
      return obj;
    },
    dataForShareByUid(state) {
      let obj = {
        uid: state.user.uid,
        fb: state.social.fb,
        line: state.social.line,
        ig: state.social.ig,
        sid: state.user.sid,
        utmSource: state.utm.utmSource,
        utmMedium: state.utm.utmMedium,
        utmCampaign: state.utm.utmCampaign,
        utmContent: state.utm.utmContent,
        utmTerm: state.utm.utmTerm,
        utmCode: state.utm.utmCode,
      };
      return obj;
    },
    dataForGetResultByUid(state) {
      let obj = {
        uid: state.otherUid,
        sid: '',
        utmSource: state.utm.utmSource,
        utmMedium: state.utm.utmMedium,
        utmCampaign: state.utm.utmCampaign,
        utmContent: state.utm.utmContent,
        utmTerm: state.utm.utmTerm,
        utmCode: state.utm.utmCode,
      };
      return obj;
    },
    dataForSaveUid(state) {
      let obj = {
        uid: state.user.uid,
        sid: state.user.sid,
        nickname: state.user.nickName,
        answer: {
          q1: state.user.answer.q1,
          q2: state.user.answer.q2,
          q3: state.user.answer.q3,
          q4: state.user.answer.q4,
          q5: state.user.answer.q5,
          q6: state.user.answer.q6,
        },
        result: state.user.result,
        utmSource: state.utm.utmSource,
        utmMedium: state.utm.utmMedium,
        utmCampaign: state.utm.utmCampaign,
        utmContent: state.utm.utmContent,
        utmTerm: state.utm.utmTerm,
        utmCode: state.utm.utmCode,
      };
      return obj;
    },
    getActiveZips(state) {
      if (state.acitveCity === '') return;
      let data = state.cityInfo.find(function (item) {
        return item.cityId === state.acitveCity;
      });
      return data.zips;
    },
  },
  // 操作原始資料
  actions: {
    openPopup(type) {
      this.$patch((state) => {
        state.popup = type;
      });
    },
    closePopup() {
      this.$patch((state) => {
        state.popup = null;
      });
    },
    setCityInfo(citys) {
      this.$patch((state) => {
        state.cityInfo = citys;
      });
    },
    setSid(id) {
      this.$patch((state) => {
        state.user.sid = id;
      });
    },
    setUid(id) {
      this.$patch((state) => {
        state.user.uid = id;
      });
    },
    setUserName(name) {
      this.$patch((state) => {
        state.user.name = name;
      });
    },
    setNickName(nickname) {
      this.$patch((state) => {
        state.user.nickName = nickname;
      });
    },
    setAnswer(q, a) {
      this.$patch((state) => {
        state.user.answer[q] = a;
      });
    },
    setUtm(obj) {
      this.$patch((state) => {
        state.utm = obj;
      });
    },
    setUserPhone(tel) {
      this.$patch((state) => {
        state.user.phoneNum = tel;
      });
    },
    setResult(type) {
      this.$patch((state) => {
        state.user.result = type;
      });
    },
    setActiveCity(city) {
      this.$patch((state) => {
        state.acitveCity = city;
      });
    },
    setActiveZipCode(code) {
      this.$patch((state) => {
        state.activeZipCode = code;
      });
    },
    setOtpToken(token) {
      this.$patch((state) => {
        state.otp.otpToken = token;
      });
    },
    setOtpCode(code) {
      this.$patch((state) => {
        state.otp.otpCode = code;
      });
    },
    setBuyHouse(ans) {
      this.$patch((state) => {
        state.user.buyHouse = ans;
      });
    },
    setSellHouse(ans) {
      this.$patch((state) => {
        state.user.sellHouse = ans;
      });
    },
    setAddress(address) {
      this.$patch((state) => {
        state.address = address;
      });
    },
    setRoadName(name) {
      this.$patch((state) => {
        state.roadName = name;
      });
    },
    setShowForm(status) {
      this.$patch((state) => {
        state.showForm = status;
      });
    },
    setChangeBtn(status) {
      this.$patch((state) => {
        state.changeBtn = status;
      });
    },
    setSocial(media) {
      this.$patch((state) => {
        state.social = {
          fb: false,
          line: false,
          ig: false,
        };
        state.social[media] = true;
      });
    },
    setShareUrl(url) {
      this.$patch((state) => {
        state.shareUrl = url;
      });
    },
    setOtherUid(uid) {
      this.$patch((state) => {
        state.otherUid = uid;
      });
    },
    setOtherUserInfo(info) {
      this.$patch((state) => {
        state.otherUserInfo = info;
      });
    },
    setStoreId(id) {
      this.$patch((state) => {
        state.storeId = id;
      });
    },
    setAgentId(id) {
      this.$patch((state) => {
        state.agentId = id;
      });
    },
    setBgColor(color) {
      this.$patch((state) => {
        state.resultBgColor = color;
      });
    },
    setLoading(status) {
      this.$patch((state) => {
        state.isLoading = status;
      });
    },
    replayReset() {
      this.$patch((state) => {
        state.user.sid = '';
        state.user.nickName = '';
        state.user.answer = {
          q1: '',
          q2: '',
          q3: '',
          q4: '',
          q5: '',
          q6: '',
        };
        state.user.result = '';
        state.otp = {
          otpToken: '',
          otpCode: '',
        };
        state.social = {
          fb: false,
          line: false,
          ig: false,
        }
        state.changeBtn = false;
        state.showForm = false;
      });
    }
  },
});
