<template lang="pug">
  main#main

    transition(
      v-if="isMobile"
      name="fade"
      mode="in-out"
      @before-enter="onBeforeEnter"
      @leave="onLeave"
      @after-leave="onAfterLeave"
    )
      router-view
    DesktopPage(v-else)
</template>

<script>
import { mapState, mapMutations } from "vuex";
import DesktopPage from '../views/DesktopPage.vue'

export default {
  name: "Main",
  props: {
    // isMobile: Boolean,
  },
  computed: {
    ...mapState([]),
  },
  data: () => {
    return {
      isMobile: true,
      screenWidth:0,
    };
  },
  watch: {
    $route(to, from) {
      const scrollTop =
        document.documentElement.scrollTop || document.body.scrollTop || 0;
      let currentTarget, nextTarget;

      // 不同頁切換
      const currentName =
        from.path === "/" ? "home" : from.path.replace("/", "");
      currentTarget = document.querySelector(`.page-${currentName}`);

      // if (currentTarget) {
      //   currentTarget.style.position = "fixed";
      //   currentTarget.style.top = `${scrollTop * -1}px`;
      // }

      // window.scrollTo({
      //   top: 0,
      //   left: 0,
      //   behavior: 'smooth'
      // });
    },
  },
  methods: {
    ...mapMutations([]),
    onBeforeEnter() {},
    onLeave() {
      // const sections = document.querySelectorAll(".section");
      // sections[1].classList.add("play");
    },
    onAfterLeave() {},
    isMobileFun() {
      this.screenWidth = window.innerWidth;
      if (this.screenWidth > 1024) {
        this.isMobile = false;
      } else {
        this.isMobile = true;
      }
    },
  },
  created() {
    this.isMobileFun();
    window.addEventListener("resize", () => {
      this.isMobileFun();
    });
  },
  mounted() {},
  components: {
    DesktopPage,
  },
};
</script>

