  // position: relative;
  width: 100%;
  height: auto;
  min-height: calc(var(--vh, 1vh) * 100);
  margin: 0 auto;
  z-index: 1;

  .page {
    width: 100%;
    height: auto;
    min-height: calc(var(--vh, 1vh) * 100);
    @include tablet {
    }
  }
}

.section {
  @include tablet {
    display: flex;
    align-items: center;
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    // min-height: vwM(1920);
  }
}

.section__inner {
  @include tablet {
    // width: vwM(1080);
    // height: vwM(1920);
  }
}
</style>
