<template lang="pug">
  #app

    // Loading 畫面
    transition(name="fade")
      Loading(v-if="isLoading")

    // Container
    #container(:class="{'is-popup': isPopup}" ref="container")
      Header
      Main(:isMobile="isMobile")
      
    transition(
      name="fade"
      @before-enter="onPopupBeforeEnter"
      @after-enter="onPopupAfterEnter"
      @before-leave="onPopupBeforeLeave"
      @after-leave="onPopupAfterLeave"
    )
      //- #popup(v-if="popup")
      //-   .popup__container
          //- PopupRule(v-if="popup.type === 'rule'")
          //- PopupWarning(v-if="popup.type === 'warning'")
</template>

<script>
// import { mapState, mapMutations } from "vuex";
import { mixins } from '@/utils/mixins';
import preload from '@/json/preload.json';

import Loading from './components/Loading.vue';
import Header from './components/Header.vue';
import Main from './components/Main.vue';
import PopupRule from './components/PopupRule.vue';
import PopupWarning from './components/PopupWarning.vue';
import axios from 'axios';
import { mapState } from 'pinia';
import { useMainStore } from '@/store/main';
export default {
  name: 'Index',
  mixins: [mixins],
  computed: {
    ...mapState(useMainStore, ['isLoading']),
  },
  data: () => {
    return {
      isMobile: null,
      isPopup: false,
      // formCitys: null,
    };
  },
  watch: {
    $route(to, from) {
      // 進入頁面時，預先載入其他頁面圖檔
      // this.preloadImages(to.path);
    },
  },
  methods: {
    // ...mapMutations(["setLoading", "setPopup","setCitysData"]),
    setCssVariable() {
      // 設定 CSS 變數
      const vh = window.innerHeight * 0.01;
      document.documentElement.style.setProperty('--vh', `${vh}px`);
    },
    checkIsMobile() {
      // 檢查是否為手機版斷點尺寸
      this.isMobile = window.matchMedia('(max-width: 1080px)').matches;
    },
    onResize() {
      const { setCssVariable, checkIsMobile } = this;
      setCssVariable();
      checkIsMobile();
    },
    onPopupBeforeEnter() {
      const { container } = this.$refs;
      let scrollTop =
        document.documentElement.scrollTop || document.body.scrollTop || 0;
      this.isPopup = true;
      container.style.top = -scrollTop + 'px';
      window.scrollTo(0, 0);
    },
    onPopupAfterEnter() {
      const popup = document.querySelector('#popup');
      popup.classList.add('ready');
    },
    onPopupBeforeLeave() {
      const popup = document.querySelector('#popup');
      popup.classList.remove('ready');
    },
    onPopupAfterLeave() {
      const { container } = this.$refs;
      const containerTop = Math.abs(parseInt(container.style.top));
      this.isPopup = false;
      container.style.top = 0 + 'px';
      this.$nextTick(() => {
        window.scrollTo(0, containerTop);
      });
    },
    preloadImages(key) {
      const preloadArray = preload[key];
      if (preloadArray) {
        preloadArray.forEach((item) => {
          const image = new Image();
          image.src = require(`@/assets/images/${item}`);
        });
      }
    },
    apiTest() {
      // let { formCitys } = this;
      const { setCitysData } = this;
      const obj = {
        sid: '',
        utmSource: '',
        utmMedium: '',
        utmCampaign: '',
        utmContent: '',
        utmTerm: '',
        utmCode: '',
      };
      axios
        .post('/api/data/getCitys', obj)
        .then(function (res) {
          console.log(res);
          const { rs, msg, item } = res.data;
          const { citys } = item.content.cityInfo;
          setCitysData(citys);
          // formCitys = citys;
          // console.log(formCitys);
          // if (rs !== "OK") {
          //   alert("發生錯誤，請稍後再試");
          //   return;
          // }
          // if (msg && item === null) {
          //   alert(msg);
          //   return;
          // }
          // if (item === null) {
          //   return;
          // }
          // console.log(res);
        })
        .catch((error) => {
          // this.$router.push({ path: /home });
          console.error(error);
        });
    },
  },
  created() {
    const { onResize } = this;
    window.addEventListener('resize', onResize);

    // if (!this.isDev()) {
    //   this.$router.push("/").catch((err) => {
    //     err;
    //   });
    // }
  },
  mounted() {
    const { setCssVariable, checkIsMobile, setLoading, preloadImages } = this;

    setCssVariable();
    checkIsMobile();
    // console.log(this.$route)
    // preloadImages(this.$route.path);

    // window.addEventListener("load", () => {
    //   setTimeout(() => {
    //     setLoading(false);
    //   }, 250);
    // });
    // this.apiTest();
  },
  components: {
    Loading,
    Header,
    Main,
    PopupRule,
    PopupWarning,
  },
};
</script>

<style lang="scss">
:root {
  --move-y: 50px;
  @include tablet {
    --move-y: #{vwM(50)};
  }
}

#app {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#container {
  position: relative;
  width: 100%;
  margin: 0 auto;
  z-index: 1;
  @include tablet {
  }
  &.is-popup {
    position: fixed;
  }
}

input[type='text'] {
  font-family: $fontFamilyNotoSans;
  font-weight: 500;
  margin: 0;
  padding: 0;
  border: 0;
  appearance: none;
  outline: 0;
}

::placeholder,
:-ms-input-placeholder,
::-ms-input-placeholder {
  color: #fcab56;
  opacity: 1;
}

#popup {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: auto;
  min-height: 100%;
  z-index: 2;
  // &.fade-leave-active {
  // }
}

.popup__container {
  display: flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  width: 100%;
  height: auto;
  min-height: 100%;
  background: rgba(#000, 0.8);
}

.popup__main {
  display: flex;
  flex-direction: column;
  position: relative;
  color: #fff;
  margin: 0 0;
  @include tablet {
    margin: 0 0;
  }
  a {
    color: #fff;
  }
}

.popup__header {
  display: flex;
  align-items: stretch;
  justify-content: center;
}

.popup__close {
  position: absolute;
  top: 0;
  left: 0;
  // width: 0;
  // height: 0;
  // background: none;
  background-size: contain;
  z-index: 1;
}

.move-in {
  @include moveFadeDefault($value: var(--move-y));
  @at-root .section.play .move-in {
    @include moveFadeIn();
  }
}

.fade-enter-active,
.fade-leave-active {
  transition-property: opacity;
  transition-duration: $primaryDuration;
  transition-timing-function: ease;
}

.fade-enter-active {
  transition-delay: 0s;
}

.fade-enter,
.fade-leave-active {
  opacity: 0;
}
</style>
