<script>
import { mapActions, mapState } from "pinia";
import { useMainStore } from "@/store/main";
import { mixins } from "@/utils/mixins";
import axios from "axios";
import PopupForm from "./PopupForm.vue";
import json from "@/json/data.json";

export default {
  name: "ChoiceResult",
  mixins: [mixins],
  props: ["finalImgUrl", "finalResult", "hasUid"],
  watch: {},
  data: () => {
    return {
      showPopup: false,
      showSocialPopup: false,
      popupPosition: null,
      // changeBtn: false,
    };
  },
  computed: {
    ...mapState(useMainStore, [
      "dataForShareByUid",
      "shareUrl",
      "changeBtn",
      "showForm",
      "quizType",
      "otherUid",
    ]),
  },
  methods: {
    ...mapActions(useMainStore, [
      "setSocial",
      "setChangeBtn",
      "setShowForm",
      "replayReset",
      "setLoading",
    ]),
    showPopupAct() {
      const { pushDataLayer } = this;
      this.setShowForm(!this.showForm);
      const bodyItem = document.querySelector("body");
      if (this.showForm) {
        this.popupPosition = window.scrollY;
        bodyItem.classList.add("scroll-style");
        // this.setChangeBtn(!this.changeBtn);
      } else {
        bodyItem.classList.remove("scroll-style");
      }
      pushDataLayer("立即填單");
    },
    hidePopupAct() {
      this.showSocialPopup = false;
      this.removeScrollStyle();
    },
    removeScrollStyle() {
      const bodyItem = document.querySelector("body");
      bodyItem.classList.remove("scroll-style");
      bodyItem.style.removeProperty("top");
    },
    addScrollStyle() {
      const bodyItem = document.querySelector("body");
      this.scrollPosition = window.scrollY;
      bodyItem.classList.add("scroll-style");
    },
    shareSocial(media) {
      const { $pushDataLayer, quizType } = this;
      const self = this;
      self.setSocial(media);
      self.setLoading(true);
      axios
        .post("/api/data/shareByUid", self.dataForShareByUid)
        .then(function (res) {
          console.log(res);
          self.setLoading(false);

          const { rs, msg, item } = res.data;
          if (self.dataForShareByUid.fb) {
            self.showSocialPopup = true;
            self.addScrollStyle();
          }

          // self.setUid(item.content.uid);
          // const { citys } = item.content.cityInfo;
          // const sid = item.sid;
          // const uid = item.content.uid;
          // self.setCityInfo(citys);
          // self.setSid(sid);
          // self.setUid(uid);
          // formCitys = citys;
          // console.log(formCitys);
          // if (rs !== "OK") {
          //   alert("發生錯誤，請稍後再試");
          //   return;
          // }
          // if (msg && item === null) {
          //   alert(msg);
          //   return;
          // }
          // if (item === null) {
          //   return;
          // }
          // console.log(res);
        })
        .catch((error) => {
          // this.$router.push({ path: /home });
          console.error(error);
        });
      $pushDataLayer({
        event: "syev_2023tvc",
        sy_event: "share",
        share_method: media === "fb" ? "facebook" : "line",
        quiz_type: quizType,
      });
    },
    replay() {
      const { pushDataLayer } = this;
      this.replayReset();
      if (this.otherUid !== 0) {
        this.$router.push({
          path: "/",
          query: { uid: this.otherUid },
        });
      } else {
        this.$router.push("/");
      }

      pushDataLayer("再玩一次");
    },
    pushDataLayer(text) {
      const { $pushDataLayer, quizType } = this;
      $pushDataLayer({
        event: "syev_2023tvc",
        sy_event: "result_click",
        click_name: text,
        quiz_type: quizType,
      });
    },
  },
  created() {},
  mounted() {
    const { pushDataLayer } = this;
    const { finalImg } = this.$refs;
    finalImg.addEventListener("long-press", () => {
      pushDataLayer("存圖分享");
    });
  },
  destroyed() {},
  components: {
    PopupForm,
  },
};
</script>

