import Vue    from 'vue'
import Index  from './Index.vue'
import router from './router'
import pinia  from './store/'
import VueCookies from 'vue-cookies'
import smoothscroll from 'smoothscroll-polyfill'
import 'current-device'

// import VConsole from 'vconsole';
// new VConsole();

import 'reset-css'
import '@/assets/styles/abstracts/_utilities.scss'
import '@/assets/styles/base/_fonts.scss'
import '@/assets/styles/common.scss'

smoothscroll.polyfill();

Vue.use(VueCookies, { expires: '33d'})
import VueGtag from 'vue-gtag'
Vue.use(VueGtag, {
  config: {
    id: '',
    params: {
      send_page_view: true
    }
  }
});

Vue.prototype.$trackPage = function(pageName) {
  this.$gtag.pageview({ page_path: '/' + pageName })
}

Vue.prototype.$trackEvent = function(category, action, label) {
  this.$gtag.event(action, {
    'event_category': category,
    'event_label': label
  })
}

window.dataLayer = window.dataLayer || [];

Vue.prototype.$pushDataLayer = function(payload) {
  window.dataLayer.push(payload)
  // if (process.env.VUE_APP_ENV === 'development') console.log('dataLayer: ', payload);
  console.log('dataLayer: ', payload);
}

// 切換頁面置頂
router.afterEach((to, from, next) => {
	window.scrollTo(0, 0);
});
