          <div
            class="choice-options-style"
            :class="[
              { 'option-extra': option.isExtra },
              { disFunc: disabledClick },
            ]"
            v-for="(option, index) in currentQuiz.options"
            :key="index"
            @click="nextQuiz(option)"
          >
            <template>
              {{ option.text }}
            </template>
          </div>
        </div>
      </div>
      <div
        class="btn-prev"
        @click="prevQuiz(currentQuiz.options)"
        v-if="currentQuiz.isPrev"
      >
        回到上一題
      </div>
      <div class="progress-bar">
        <div
          class="progress-dot"
          v-for="(quizItem, index) in quizData"
          :key="index"
          :class="{ 'completed-dot': index <= currentIndex }"
        ></div>
      </div>
    </section>
