import Vue from 'vue'
import VueRouter from 'vue-router'
import HomePage from '@/views/HomePage.vue'
import ChoicePage from '@/views/ChoicePage.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    name: 'HomePage',
    component: HomePage,
  },
  {
    path: '/choice',
    name: 'ChoicePage',
    component: ChoicePage
  },
  // {
  //   path: '/sample',
  //   name: 'SamplePage',
  //   // route level code-splitting
  //   // this generates a separate chunk (about.[hash].js) for this route
  //   // which is lazy-loaded when the route is visited.
  //   component: () => import(/* webpackChunkName: "sample" */ '@/views/SamplePage.vue')
  // },
  // {
  //   path: '/sample/:param?',
  //   name: 'SamplePage',
  //   component: () => import(/* webpackChunkName: "game" */ '@/views/SamplePage.vue')
  // },
  {
    path: '*',
    redirect: '/',
  },
]

const router = new VueRouter({
  mode: 'hash',
  base: process.env.BASE_URL,
  routes
})

export default router
