<template>
  <main id="home" class="main__block" :class="{ pairing: hasUid }">
    <article>
      <section class="part01__block" @click="nextPart('trans')">
        <div class="index__block" v-if="currentPart === 'home'">
          <h1 class="index-title">幸福交心試</h1>
          <p class="index-text">
            想知道和最在乎的人<br />心的距離有多遠？<br />現在就用多一分的理解<br />試出彼此信任的答案！
          </p>
          <div class="index-tickets">
            <!-- <p>2023/11/30前完成6題<br />抽蘭城晶英住宿券分享結果加碼抽</p>
            <p>
              <strong>星宇航空<br />東京雙人來回機票</strong>
            </p> -->
          </div>
          <div class="index-btn" v-if="!hasUid">開始交心</div>
          <div class="index-btn" v-else>
            開始與<br />
            <p class="another-name">{{ anotherName }}</p>
            交心
          </div>
          <PeopleSlider />
        </div>
        <!-- 轉場 -->
        <transition name="fade" mode="out-in">
          <div class="trans__block" v-if="currentPart === 'trans'" @click.stop="skip()">
            <p class="trans-title">開始前...</p>
            <p class="trans-text" v-if="!hasUid">
              想好要和誰交心了嗎？<br />作答時，請把<span>「對方」</span
              ><br />想成心中最重要的人！
            </p>
            <p class="trans-text" v-else>
              準備好交心了嗎？<br />作答時，請把「對方」<br />想成是<span
                class="match-name"
                >{{ anotherName }}</span
              >吧！
            </p>
            <div class="trans-click">點擊畫面直接開始</div>
            <PeopleSlider />
          </div>
        </transition>
      </section>
    </article>
  </main>
</template>

<script>
import { mapActions, mapState } from "pinia";
import { useMainStore } from "@/store/main";
import axios from "axios";
import { mixins } from "@/utils/mixins";

import PeopleSlider from "./PeopleSlider.vue";

export default {
  name: "Home",
  mixins: [mixins],
  props: {},
  watch: {},
  data: () => {
    return {
      isReady: true,
      isOut: false,
      currentPart: "home",
      hasUid: false,
      anotherName: "",
      time:''
    };
  },
  computed: {
    ...mapState(useMainStore, [
      "footerStatus",
      "dataForGetCitys",
      "dataForGetResultByUid",
      "quizType",
    ]),
  },
  methods: {
    ...mapActions(useMainStore, [
      "setCityInfo",
      "setSid",
      "setUtm",
      "setUid",
      "setOtherUid",
      "setOtherUserInfo",
      "setLoading",
      "setStoreId",
      "setAgentId"
    ]),
    nextPart(part) {
      const { quizType } = this;
      this.currentPart = part;
      this.time = setTimeout(() => {
        this.$router.push("/choice");
        this.currentPart = 'choice';
      }, 2000);
      // this.$pushDataLayer({
      //   event: "syev_2023tvc",
      //   sy_event: "quiz_start",
      //   quiz_type: quizType
      // });
    },
    skip() {
      clearTimeout(this.time)
      this.$router.push("/choice");
    },
    // 取得城市資料 uid sid
    getCityData() {
      const self = this;
      self.setLoading(true)
      axios
        .post("/api/data/getCitys", self.dataForGetCitys)
        .then(function (res) {
          console.log(res);
          const { rs, msg, item } = res.data;
          const { citys } = item.content.cityInfo;
          const sid = item.sid;
          // const uid = item.content.uid;
          self.setCityInfo(citys);
          self.setSid(sid);
          self.setLoading(false)
          // self.setUid(uid);
          // formCitys = citys;
          // console.log(formCitys);
          // if (rs !== "OK") {
          //   alert("發生錯誤，請稍後再試");
          //   return;
          // }
          // if (msg && item === null) {
          //   alert(msg);
          //   return;
          // }
          // if (item === null) {
          //   return;
          // }
          // console.log(res);
        })
        .catch((error) => {
          // this.$router.push({ path: /home });
          console.error(error);
          self.setLoading(false)
        });
    },
    // 取得 UTM 資料
    getUtm() {
      // 做一些事情去拿 UTM，然後塞進去 pinia
      const self = this;
      const utmObj = {
        utmSource: "",
        utmMedium: "",
        utmCampaign: "",
        utmContent: "",
        utmTerm: "",
        utmCode: "",
      };
      const { getParameterByName } = this;
      // if (self.$route.query.utm_source) {
      //   utmObj.utmSource = self.$route.query.utm_source;
      // }
      // if (self.$route.query.utm_medium) {
      //   utmObj.utmMedium = self.$route.query.utm_medium;
      // }
      // if (self.$route.query.utm_campaign) {
      //   utmObj.utmCampaign = self.$route.query.utm_campaign;
      // }
      // if (self.$route.query.utm_content) {
      //   utmObj.utmContent = self.$route.query.utm_content;
      // }
      // if (self.$route.query.utm_term) {
      //   utmObj.utmTerm = self.$route.query.utm_term;
      // }
      // if (self.$route.query.utm_code) {
      //   utmObj.utmCode = self.$route.query.utm_code;
      // }
      utmObj.utmSource = getParameterByName('utm_source') || self.$route.query.utm_source || '';
      utmObj.utmMedium = getParameterByName('utm_medium') || self.$route.query.utm_medium || '';
      utmObj.utmCampaign = getParameterByName('utm_campaign') || self.$route.query.utm_campaign || '';
      utmObj.utmContent = getParameterByName('utm_content') || self.$route.query.utm_content || '';
      utmObj.utmTerm = getParameterByName('utm_term') || self.$route.query.utm_term || '';
      utmObj.utmCode = getParameterByName('utm_code') || self.$route.query.utm_code || '';
      self.setUtm(utmObj);
    },
    getOtherInfo() {
      const self = this;
      self.setLoading(true)
      axios
        .post("/api/data/getResultByUid", self.dataForGetResultByUid)
        .then(function (res) {
          console.log('測試',res);
          const { rs, msg, item } = res.data;
          self.setOtherUserInfo(item.content);
          self.setSid(item.sid);

          console.log("另一人", item.content);
          self.anotherName = item.content.nickName;
          self.setLoading(false)
          // console.log(self.anotherName);
          // const { citys } = item.content.cityInfo;
          // const sid = item.sid;
          // const uid = item.content.uid;
          // self.setCityInfo(citys);
          // self.setSid(sid);
          // self.setUid(uid);
          // formCitys = citys;
          // console.log(formCitys);
          // if (rs !== "OK") {
          //   alert("發生錯誤，請稍後再試");
          //   return;
          // }
          // if (msg && item === null) {
          //   alert(msg);
          //   return;
          // }
          // if (item === null) {
          //   return;
          // }
          // console.log(res);
        })
        .catch((error) => {
          // this.$router.push({ path: /home });
          console.error(error);
          self.setLoading(false)
        });
    },
    init() {
      const { getParameterByName } = this;
      const self = this;
      self.getUtm();
      if(getParameterByName('storeId')){
        self.setStoreId(getParameterByName('storeId'))
      }
      if(getParameterByName('agentId')){
        self.setAgentId(getParameterByName('agentId'))
      }
      // 雙人模式
      // if (getParameterByName('uid') || self.$route.query.uid) {
      //   const uid = getParameterByName('uid') || self.$route.query.uid;
      //   self.getCityData();
      //   self.setOtherUid(parseInt(uid, 10));
      //   self.getOtherInfo();
      //   self.hasUid = true;
      // }
      // // 單人模式
      // else {
      //   self.getCityData();
      // }
    },
  },
  created() {
    console.log(this.$route);
  },
  mounted() {
    if(this.$cookies.get('user_uid')){
      this.setUid(parseInt(this.$cookies.get('user_uid')))
    }
    this.init();
  },
  destroyed() {},
  components: {
    PeopleSlider,
  },
};
</script>

